schema_ddl:
CREATE TABLE prodotti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    prezzo_unitario NUMERIC(10,2) NOT NULL CHECK (prezzo_unitario >= 0)
);

CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE
);

CREATE TABLE vendite (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    prodotto_id INT NOT NULL REFERENCES prodotti(id),
    cliente_id INT NOT NULL REFERENCES clienti(id),
    data_vendita DATE NOT NULL,
    importo_vendita NUMERIC(12,2) NOT NULL,
    quantita TEXT NOT NULL
);

CREATE TABLE punti_vendita (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    citta TEXT NOT NULL
);

CREATE TABLE transazioni (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    vendita_id INT NOT NULL REFERENCES vendite(id),
    punto_vendita_id INT NOT NULL REFERENCES punti_vendita(id),
    valore_transazione NUMERIC(12,2) NOT NULL,
    unita_movimentate TEXT NOT NULL
);
